class Solution{int m,n;int f(int[][]a,int r,int c,int[][]dp){if(dp[r][c]!=0)return dp[r][c];int[][]d={{1,0},{-1,0},{0,1},{0,-1}};dp[r][c]=1;for(int[]z:d){int x=r+z[0],y=c+z[1];if(x>=0&&y>=0&&x<m&&y<n&&a[x][y]>a[r][c])dp[r][c]=Math.max(dp[r][c],1+f(a,x,y,dp));}return dp[r][c];}public int longestIncreasingPath(int[][]a){if(a.length==0)return 0;m=a.length;n=a[0].length;int[][]dp=new int[m][n];int b=0;for(int i=0;i<m;i++)for(int j=0;j<n;j++)b=Math.max(b,f(a,i,j,dp));return b;}}
